#include <LVRS/ModelUndoStack.h>
#include <iiSDKCore/Core/Property/ObservableReadScope.h>
#include <iostream>
#include <thread>
using namespace ii;
namespace {
using Value=core::Value;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> result){if(!result){if(result.error().cause)std::rethrow_exception(result.error().cause);throw std::runtime_error(result.error().message);}return std::move(*result);}
void good(core::Result<void> result){if(!result)throw std::runtime_error(result.error().message);}
template<class F>auto receiver(F action){return std::make_shared<lvrs::ModelUndoChangePort>(std::move(action));}
void defaults(){lvrs::ModelUndoStack history;check(history.limit()==128&&history.undo_depth()==0&&history.redo_depth()==0&&!history.can_undo()&&!history.can_redo(),"Native history defaults differ");check(!take(history.take_undo_snapshot()).snapshot&&!take(history.take_redo_snapshot()).snapshot,"Empty history returned a snapshot");}
void values(){lvrs::ModelUndoStack history;check(!take(history.push_snapshot(std::nullopt))&&take(history.push_snapshot(Value{})),"Absent and explicit null snapshots were confused");check(!take(history.push_snapshot(Value{}))&&history.undo_depth()==1,"Consecutive duplicate snapshot was retained");auto move=take(history.take_undo_snapshot(Value(2)));check(move.snapshot==Value{}&&history.redo_depth()==1,"Explicit null could not be undone");check(take(history.take_redo_snapshot()).snapshot==Value(2)&&!history.can_undo(),"An absent current snapshot was recorded");}
void roundtrip(){lvrs::ModelUndoStack history;take(history.push_snapshot(Value("one")));take(history.push_snapshot(Value("two")));check(take(history.take_undo_snapshot(Value("three"))).snapshot==Value("two"),"Undo returned the wrong snapshot");check(take(history.take_undo_snapshot(Value("two"))).snapshot==Value("one"),"Undo order differs");check(take(history.take_redo_snapshot(Value("one"))).snapshot==Value("two")&&take(history.take_redo_snapshot(Value("two"))).snapshot==Value("three"),"Redo order differs");}
void branch(){lvrs::ModelUndoStack history;take(history.push_snapshot(Value(1)));take(history.push_snapshot(Value(2)));take(history.take_undo_snapshot(Value(3)));check(!take(history.push_snapshot(Value(1)))&&history.can_redo(),"A duplicate push unexpectedly discarded redo");take(history.push_snapshot(Value(4)));check(!history.can_redo()&&history.undo_depth()==2,"A new history branch preserved redo");}
void limit(){lvrs::ModelUndoStack history;take(history.set_limit(2));for(int n=0;n<4;++n)take(history.push_snapshot(Value(n)));check(history.undo_depth()==2&&take(history.take_undo_snapshot()).snapshot==Value(3)&&take(history.take_undo_snapshot()).snapshot==Value(2),"History limit discarded the newest snapshots");take(history.set_limit(0));check(history.limit()==1,"History limit did not clamp to one");check(!history.set_limit(INT64_MAX)&&history.limit()==1,"An unsupported history limit partially committed");}
void observation(){lvrs::ModelUndoStack history;take(history.push_snapshot(Value(1)));take(history.push_snapshot(Value(2)));std::vector<core::ObservableRead> reads;core::ObservableReadScope::collect([&](auto read){reads.push_back(std::move(read));},[&]{return history.undo_depth();});int changed=0;auto watch=reads.at(0).subscribe([&]{++changed;});take(history.set_limit(1));check(history.undo_depth()==1&&changed==1,"Trimming a limit left history depth readers stale");take(history.set_limit(2));check(changed==1,"An untrimmed limit invalidated history depth");}
void notifications(){lvrs::ModelUndoStack history;std::vector<lvrs::ModelUndoEvent> events;auto port=receiver([&](const lvrs::ModelUndoChange& change){events.push_back(change.event);check(change.undo_depth==history.undo_depth()&&change.redo_depth==history.redo_depth(),"History notification exposed a partial transition");});good(history.observe(port));take(history.push_snapshot(Value(1)));take(history.push_snapshot(Value(2)));events.clear();take(history.set_limit(1));check(events==std::vector{lvrs::ModelUndoEvent::limit,lvrs::ModelUndoEvent::stack},"History limit/stack notifications lost coherence");events.clear();check(take(history.clear())&&!take(history.clear())&&events==std::vector{lvrs::ModelUndoEvent::stack},"History clear/no-op contract differs");}
void failure(){lvrs::ModelUndoStack history;take(history.push_snapshot(Value(1)));int calls=0;auto bad=receiver([](const auto&){throw std::runtime_error("history observer");});auto next=receiver([&](const auto&){++calls;});good(history.observe(bad));good(history.observe(next));auto moved=take(history.take_undo_snapshot(Value(2)));check(moved.snapshot==Value(1)&&moved.observation_error&&calls==1&&history.redo_depth()==1,"A notification failure lost the transferred snapshot or stopped fanout");}
void reentrant(){lvrs::ModelUndoStack history;bool blocked=false;auto port=receiver([&](const auto&){auto result=history.push_snapshot(Value(9));blocked=!result&&result.error().code==core::ErrorCode::busy;});good(history.observe(port));take(history.push_snapshot(Value(1)));check(blocked&&history.undo_depth()==1,"A history observer performed a nested mutation");}
void ownership(){lvrs::ModelUndoStack history;bool blocked=false;std::thread worker([&]{auto result=history.push_snapshot(Value(1));blocked=!result&&result.error().code==core::ErrorCode::wrong_executor;try{(void)history.undo_depth();blocked=false;}catch(const std::logic_error&) {}});worker.join();check(blocked&&!history.can_undo(),"History allowed access from a foreign thread");}
void lifetime(){auto history=std::make_shared<lvrs::ModelUndoStack>();auto* raw=history.get();std::weak_ptr<lvrs::ModelUndoStack> weak=history;auto port=receiver([&](const auto&){history.reset();});good(history->observe(port));take(raw->push_snapshot(Value(1)));check(weak.expired(),"History retained an owner removed by its observer");}
void owned(){lvrs::ModelUndoStack history;Value::Object source{{"caption",Value("Original")}};take(history.push_snapshot(Value(source)));source["caption"]=Value("Changed");auto snapshot=take(history.take_undo_snapshot()).snapshot;check(snapshot&&snapshot->find("caption")->get()==Value("Original"),"History borrowed mutable caller data");}
}
int main(int argc,char** argv){try{std::string name=argc>1?argv[1]:"defaults";if(name=="defaults")defaults();else if(name=="values")values();else if(name=="roundtrip")roundtrip();else if(name=="branch")branch();else if(name=="limit")limit();else if(name=="observation")observation();else if(name=="notifications")notifications();else if(name=="failure")failure();else if(name=="reentrant")reentrant();else if(name=="ownership")ownership();else if(name=="lifetime")lifetime();else if(name=="owned")owned();else throw std::runtime_error("Unknown history case");std::cout<<"Native snapshot history "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
